"use client"

import { useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { createClient } from "@/lib/supabase/client"
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { Lock } from "lucide-react"

export function TrialChecker() {
    const [open, setOpen] = useState(false)
    const router = useRouter()

    useEffect(() => {
        const checkTrial = async () => {
            const supabase = createClient()
            const { data: { user } } = await supabase.auth.getUser()

            if (!user) return

            const { data: profile } = await supabase
                .from("profiles")
                .select("subscription_status, plan_end_date, plan, stripe_subscription_id")
                .eq("id", user.id)
                .single()

            if (profile) {
                // Se tiver assinatura ativa no Stripe, não bloquear por trial
                if (profile.stripe_subscription_id) return

                const isTrial = profile.subscription_status === 'trial'
                const isExpired = profile.plan_end_date && new Date(profile.plan_end_date) < new Date()

                // If trial expired, first try to sync with Stripe as a failsafe
                if (isTrial && isExpired) {
                    try {
                        const syncResponse = await fetch("/api/subscription/sync", {
                            method: "POST",
                        })
                        const syncData = await syncResponse.json()

                        if (syncData.success && syncData.synced) {
                            // Se sincronizou e achou algo, não bloqueia
                            return
                        }
                    } catch (err) {
                        console.error("Erro ao tentar sync de emergência:", err)
                    }

                    setOpen(true)
                }
            }
        }

        checkTrial()
    }, [])

    const handleUpgrade = () => {
        window.open("https://wa.me/258856428686", "_blank")
    }

    return (
        <AlertDialog open={open}>
            <AlertDialogContent className="max-w-md">
                <AlertDialogHeader>
                    <div className="mx-auto flex h-12 w-12 items-center justify-center rounded-full bg-red-100 dark:bg-red-900/20 mb-4">
                        <Lock className="h-6 w-6 text-red-600 dark:text-red-400" />
                    </div>
                    <AlertDialogTitle className="text-center text-xl">Seu período de teste acabou</AlertDialogTitle>
                    <AlertDialogDescription className="text-center pt-2">
                        Esperamos que você tenha gostado do OiChat! Para continuar criando agentes e atendendo seus clientes, realize o pagamento via WhatsApp para ativar sua conta.
                    </AlertDialogDescription>
                </AlertDialogHeader>
                <AlertDialogFooter className="sm:justify-center">
                    <AlertDialogAction
                        onClick={handleUpgrade}
                        className="w-full sm:w-auto bg-[#25D366] hover:bg-[#20ba5a] text-white"
                    >
                        Pagar via WhatsApp
                    </AlertDialogAction>
                </AlertDialogFooter>
            </AlertDialogContent>
        </AlertDialog>
    )
}
